<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {Plus,Folder,Search} from '@element-plus/icons-vue'
import {service} from '@/services/service'
import type {ExtractionTemplate,TemplateFolder} from '@/domain/types'
import {cloneDraft,safeFilename} from '@/domain/validation'
import {createId} from '@/domain/ids'
import FieldEditor from '@/components/FieldEditor.vue'
import ToolGlyph from '@/components/ToolGlyph.vue'
import {useWorkspace} from '@/stores/workspace'
const router=useRouter(),workspace=useWorkspace()
const templates=ref<ExtractionTemplate[]>([]),folders=ref<TemplateFolder[]>([]),folder=ref(''),query=ref(''),page=ref(1),loading=ref(false),error=ref(''),editing=ref(false),viewing=ref<ExtractionTemplate|null>(null),saving=ref(false)
const current=ref<ExtractionTemplate>({id:'',name:'',description:'',scope:'personal',folderId:'',fields:[]})
const tree=computed(()=>{const make=(scope:'system'|'personal',parent?:string):any[]=>folders.value.filter(f=>f.scope===scope&&(f.parentId||undefined)===parent).map(f=>({id:f.id,label:f.name,children:make(scope,f.id)}));return[{id:'@system',label:'系统模板',children:make('system')},{id:'@personal',label:'个人模板',children:make('personal')}]})
const visible=computed(()=>templates.value.filter(t=>(!folder.value||(folder.value==='@system'?t.scope==='system':folder.value==='@personal'?t.scope==='personal':t.folderId===folder.value))&&(!query.value||`${t.name} ${t.description}`.includes(query.value.trim()))))
const paged=computed(()=>visible.value.slice((page.value-1)*15,page.value*15))
const selectedFolder=computed(()=>folders.value.find(f=>f.id===folder.value))
const folderQuery=ref('')
const displayedTree=computed(()=>{const filter=(nodes:any[]):any[]=>nodes.flatMap(node=>{const children=filter(node.children||[]);return !folderQuery.value.trim()||node.label.includes(folderQuery.value.trim())||children.length?[{...node,children:node.label.includes(folderQuery.value.trim())?node.children:children}]:[]});return filter(tree.value)})
const currentDirectory=computed(()=>selectedFolder.value?.name||(folder.value==='@system'?'系统模板':folder.value==='@personal'?'个人模板':'全部模板'))
async function useTemplate(template:ExtractionTemplate){const draft=workspace.getDraft('extract');if(draft.config.fields.length){try{await ElMessageBox.confirm('载入模板将替换当前提取字段，已选资料保留。','使用提取模板',{confirmButtonText:'载入模板',cancelButtonText:'取消'})}catch{return}}draft.config.templateId=template.id;draft.config.fields=cloneDraft(template.fields);await router.push('/tool/extract')}
async function load(){loading.value=true;try{[templates.value,folders.value]=await Promise.all([service.listTemplates(),service.listTemplateFolders()]);error.value=''}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function edit(t?:ExtractionTemplate,copy=false){current.value=t?cloneDraft(t):{id:'',name:'',description:'',scope:'personal',folderId:selectedFolder.value?.scope==='personal'?selectedFolder.value.id:folders.value.find(f=>f.scope==='personal')?.id||'',fields:[]};if(copy){current.value.id='';current.value.name+=' · 副本';current.value.scope='personal';current.value.folderId=folders.value.find(f=>f.scope==='personal')?.id||''}editing.value=true}
async function save(){const t=current.value;if(!t.name.trim()||!t.folderId||!t.fields.length||t.fields.some(f=>!f.name.trim())){ElMessage.warning('请填写模板名称、所属目录和至少一个有效字段');return}if(new Set(t.fields.map(f=>f.name.trim())).size!==t.fields.length){ElMessage.warning('字段名称不能重复');return}saving.value=true;try{await service.saveTemplate(cloneDraft(t));editing.value=false;await load();ElMessage.success('模板已保存')}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
async function remove(t:ExtractionTemplate){try{await ElMessageBox.confirm(`删除个人模板「${t.name}」？历史分析结果不受影响。`,'删除模板',{confirmButtonText:'删除',cancelButtonText:'取消'});await service.deleteTemplate(t.id);await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
function download(t:ExtractionTemplate){const blob=new Blob([JSON.stringify({version:1,name:t.name,description:t.description,fields:t.fields.map(({name,description})=>({name,description}))},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=safeFilename(t.name)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
async function importTemplate(e:Event){const input=e.target as HTMLInputElement;const file=input.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('模板文件不能超过 2 MB');const data=JSON.parse(await file.text());if(typeof data.name!=='string'||!Array.isArray(data.fields)||data.fields.some((f:any)=>typeof f.name!=='string'))throw Error('模板格式不正确，需要模板名称和字段列表');edit();current.value.name=data.name;current.value.description=String(data.description||'');current.value.fields=data.fields.map((f:any)=>({id:createId(),name:f.name,description:String(f.description||'')}))}catch(e){ElMessage.error((e as Error).message)}finally{input.value=''}}
async function manageFolder(action:'create'|'rename'|'delete'){try{if(action==='delete'){if(!selectedFolder.value)return;await ElMessageBox.confirm(`删除目录「${selectedFolder.value.name}」？请先移出目录内的模板。`,'删除目录',{confirmButtonText:'删除',cancelButtonText:'取消'});await service.deleteTemplateFolder(selectedFolder.value.id);folder.value='@personal'}else{const {value}=await ElMessageBox.prompt('填写目录名称',action==='create'?'新建个人模板目录':'重命名目录',{inputValue:action==='rename'?selectedFolder.value?.name:'',inputValidator:v=>!!v.trim()||'请填写名称'});await service.saveTemplateFolder({id:action==='rename'?selectedFolder.value!.id:'',name:value.trim(),scope:'personal',parentId:action==='create'&&selectedFolder.value?.scope==='personal'?selectedFolder.value.id:selectedFolder.value?.parentId})}await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error((e as Error).message)}}
onMounted(load)
</script>
<template>
 <div class="template-page"><div class="template-layout">
  <aside class="template-sidebar"><div class="category-heading"><h2>模板分类</h2><el-button v-if="service.capabilities.templateFolders" :icon="Plus" text aria-label="新建个人模板目录" @click="manageFolder('create')"/></div><div class="category-search"><el-input v-model="folderQuery" placeholder="查找分类" aria-label="查找模板分类" clearable :prefix-icon="Search"/></div><el-tree :data="displayedTree" node-key="id" default-expand-all highlight-current @node-click="(node:any)=>{folder=node.id;page=1}"><template #default="{data}"><span class="folder-node"><el-icon><Folder/></el-icon>{{data.label}}</span></template></el-tree><div class="folder-actions" v-if="selectedFolder?.scope==='personal'&&service.capabilities.templateFolders"><el-button text @click="manageFolder('rename')">重命名</el-button><el-button text @click="manageFolder('delete')">删除目录</el-button></div></aside>
  <section class="template-list" v-loading="loading">
   <header class="template-toolbar"><div class="template-location"><h1>提取模板</h1><span :title="currentDirectory">{{currentDirectory}}</span></div><el-input v-model="query" clearable :prefix-icon="Search" placeholder="查找模板名称或描述" aria-label="查找模板" @input="page=1"/><div class="actions"><label class="import-template">导入模板<input type="file" accept=".json" @change="importTemplate" aria-label="导入模板"/></label><el-button type="primary" :icon="Plus" @click="edit()">新增模板</el-button></div></header>
   <el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="error" @click="load">重试</el-button>
   <el-table :data="paged" class="template-table" height="100%"><el-table-column label="模板名称" min-width="240"><template #default="{row}"><div class="template-name"><ToolGlyph tool="extract"/><div><button class="template-open" @click="viewing=row" :title="'查看 '+row.name+' 的字段'">{{row.name}}</button><p class="template-folder">{{row.scope==='system'?'系统模板':'个人模板'}} / {{folders.find(f=>f.id===row.folderId)?.name||'未分类'}}</p></div></div></template></el-table-column><el-table-column prop="description" label="描述" min-width="250" show-overflow-tooltip/><el-table-column label="字段数" width="90"><template #default="{row}"><strong class="number">{{row.fields.length}}</strong> 个</template></el-table-column><el-table-column label="操作" min-width="340"><template #default="{row}"><div class="template-actions"><el-button link type="primary" @click="useTemplate(row)">使用模板</el-button><el-button link type="primary" @click="viewing=row">查看字段</el-button><el-button v-if="row.scope==='personal'" link type="primary" @click="edit(row)">编辑</el-button><el-button link type="primary" @click="edit(row,true)">复制模板</el-button><el-button link type="primary" @click="download(row)">导出配置</el-button><el-button v-if="row.scope==='personal'" link type="danger" @click="remove(row)">删除</el-button></div></template></el-table-column></el-table>
   <footer class="template-pagination"><span class="muted">共 <strong class="number">{{visible.length}}</strong> 个模板</span><el-pagination v-model:current-page="page" :page-size="15" :total="visible.length" layout="prev,pager,next"/></footer>
  </section>
 </div>
 <el-dialog v-model="editing" :title="current.id?'编辑提取模板':'新增提取模板'" width="900px" :close-on-click-modal="false"><div class="template-form"><el-form label-position="top"><el-form-item label="模板名称" required><el-input v-model="current.name" maxlength="100"/></el-form-item><el-form-item label="所属目录" required><el-select v-model="current.folderId" style="width:100%"><el-option v-for="f in folders.filter(f=>f.scope==='personal')" :key="f.id" :label="f.name" :value="f.id"/></el-select></el-form-item><el-form-item label="模板描述"><el-input v-model="current.description" type="textarea" :rows="2"/></el-form-item></el-form><FieldEditor v-model="current.fields"/></div><template #footer><el-button @click="editing=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存模板</el-button></template></el-dialog>
 <el-dialog :model-value="!!viewing" @update:model-value="viewing=null" :title="viewing?.name+' · 提取字段'" width="850px"><el-table :data="viewing?.fields" max-height="500"><el-table-column type="index" label="序号" width="70"/><el-table-column prop="name" label="字段名称" min-width="180"/><el-table-column prop="description" label="提取说明" min-width="320"/></el-table><template #footer><el-button @click="viewing=null">关闭</el-button></template></el-dialog>
 </div>
</template>
<style scoped>
.template-page{height:100%;padding:8px 10px;container-type:inline-size;container-name:templates}.template-layout{display:grid;grid-template-columns:240px minmax(0,1fr);height:100%;min-height:0;background:#fff;border:1px solid #e6ebf1;border-radius:9px;overflow:hidden}.template-sidebar{overflow:auto;border-right:1px solid #e6ebf1;padding:0 6px 12px;background:#fafcff}.category-heading{display:flex;align-items:center;justify-content:space-between;min-height:52px;padding:0 8px}.category-heading h2{font-size:16px}.category-search{padding:0 4px 10px}.folder-node{display:flex;align-items:center;gap:8px;min-width:0;font-size:16px}.folder-node .el-icon{color:#aa7a45}.template-sidebar :deep(.el-tree-node__content){height:40px;border-radius:5px}.template-sidebar :deep(.el-tree){background:transparent}.template-list{display:flex;flex-direction:column;min-height:0;min-width:0;overflow:hidden}.template-toolbar{padding:8px 12px;min-height:56px;display:flex;gap:12px;align-items:center;border-bottom:1px solid #e6ebf1;flex:none}.template-location{display:flex;gap:12px;align-items:center;min-width:0}.template-location h1{font-size:18px;white-space:nowrap}.template-location>span{font-size:14px;min-width:0;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#596b80}.template-toolbar>.el-input{min-width:160px;max-width:300px;flex:1;margin-left:auto}.template-toolbar .actions{flex:none}.template-table{flex:1;min-height:0}.template-name{display:flex;align-items:center;gap:10px;min-width:0}.template-name>div{min-width:0}.template-open{background:none;border:0;padding:0;text-align:left;color:#245ec5;font-size:16px;line-height:1.6}.template-folder{font-size:14px;color:#596b80;line-height:1.6;margin-top:2px;overflow-wrap:anywhere}.template-actions{display:flex;gap:10px;flex-wrap:wrap}.template-actions .el-button{font-size:14px}.template-table :deep(.el-table__cell){padding:12px 0}.template-pagination{padding:8px 12px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex:none;border-top:1px solid #e6ebf1}.import-template{position:relative;display:flex;align-items:center;min-height:36px;border:1px solid #dce3ed;border-radius:8px;padding:4px 12px;font-size:16px;white-space:nowrap;background:white;cursor:pointer}.import-template:focus-within{outline:2px solid #3269db;outline-offset:2px}.import-template input{position:absolute;inset:0;opacity:0;width:100%;cursor:pointer}.template-form{padding-right:6px}.folder-actions{margin:12px 0;display:flex}.template-form :deep(.field-item){background:#fafbfd}
@container templates (max-width:999px){.template-layout{grid-template-columns:220px minmax(0,1fr)}.template-location>span{display:none}.template-toolbar{gap:8px;flex-wrap:wrap}.template-toolbar>.el-input{max-width:none}.template-toolbar .actions{margin-left:auto}.template-toolbar .el-button,.import-template{font-size:14px}}
@container templates (max-width:619px){.template-layout{grid-template-columns:1fr;grid-template-rows:160px minmax(0,1fr)}.template-page{padding:6px}.template-sidebar{border-bottom:1px solid #e6ebf1;border-right:0}.category-heading{min-height:42px}.template-toolbar{padding:8px}.template-toolbar>.el-input{order:3;flex-basis:100%;width:100%}.template-location h1{font-size:16px}.template-pagination{padding:8px}}
</style>
